/* SERVICES */
static int tx_votes;static int lpass_cdc_clk_rsc_request_clock(struct device*d,int a,int b,bool en){assert(a==0&&b==0);if(fail())return -EIO;if(en)tx_votes++;else assert(tx_votes-->0);return 0;}
/* SOURCE */
